mapper.select:
SELECT * FROM data_backup_record


        AND backup_name LIKE CONCAT('%', #{backupName}, '%')


        AND backup_type = #{backupType}


        AND status = #{status}


        AND storage_location = #{storageLocation}


        AND triggered_by = #{triggeredBy}


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}


ORDER BY create_time DESC
